-- Detailed spec-sheet descriptions (web-researched, reviewer-approved).
-- Rendered as an HTML bullet list (<ul><li>) by the storefront HtmlRender.
-- 14 mobiles + 5 laptops. Portable: keyed on slug, idempotent.
--   local: docker exec -i shop_db psql -U postgres -d shop_db < db/populate_descriptions.sql
--   prod:  psql "$DATABASE_URL" < db/populate_descriptions.sql
BEGIN;

UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.7\", 1080 x 2412 pixels, Fluid AMOLED 120Hz HDR10+ Display, 4800mAh Battery, 150W SUPERVOOC Fast Charging</li><li>128GB ROM, 8GB RAM, No SD Card Slot, Qualcomm SM8475 Snapdragon 8+ Gen 1 (4 nm), Octa-Core (1x3.19 GHz Cortex-X2 & 3x2.75 GHz Cortex-A710 & 4x1.80 GHz Cortex-A510), Adreno 730</li><li>Rear Camera: 50MP, f/1.8 + 8MP, f/2.2 (ultrawide) + 2MP, f/2.4 (macro), Front Camera: 16 MP, f/2.4, Android 12, OxygenOS 13</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 800/850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/18/19/20/25/26/28/30/32/38/39/41/46/48/66/71, 5G: Sub6 SA/NSA bands 1/2/3/5/7/8/20/25/28/30/38/41/48/66/71/77 - Dual Nano-SIM</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'oneplus-10t-moonstone-black-5g';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.1\", 1170 x 2532 pixels, Super Retina XDR OLED, HDR10/Dolby Vision Display, 2815mAh Battery, 20W Wired + 15W MagSafe Wireless Charging</li><li>64GB / 128GB / 256GB ROM, 4GB RAM, No SD Card Slot, Apple A14 Bionic (5 nm), Hexa-Core (2x3.1 GHz Firestorm + 4x1.8 GHz Icestorm), Apple 4-Core GPU</li><li>Rear Camera: 12MP, f/1.6 (Wide) + 12MP, f/2.4 (Ultrawide), Front Camera: 12 MP, f/2.2, iOS 14.1 (upgradable to iOS 18)</li><li>2G: GSM 850/900/1800/1900 + CDMA 800/1900, 3G: HSDPA 850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/20/25/28/38/40/41/66/71, 5G: Sub6/mmWave - Nano-SIM + eSIM (Dual SIM)</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'apple-iphone-12';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.7\", 1440 x 3216 pixels, LTPO2 Fluid AMOLED 120Hz HDR10+ Display, 5000mAh Battery, 50W Wireless Charging + Reverse Wireless</li><li>128GB/256GB/512GB ROM, 8GB/12GB RAM, No SD Card Slot, Qualcomm SM8450 Snapdragon 8 Gen 1 (4 nm), Octa-Core (1x3.0 GHz Cortex-X2 + 3x2.5 GHz Cortex-A710 + 4x1.8 GHz Cortex-A510), Adreno 730</li><li>Rear Camera: 48MP, f/1.8 + 50MP, f/2.2 (ultrawide) + 8MP, f/2.4 (3.3x telephoto), Front Camera: 32 MP, f/2.2, Android 12, OxygenOS 12.1</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 800/850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/18/19/20/..., 5G: SA/NSA Sub6 bands 1/3/5/7/8/28/38/40/41/77/78 - Dual SIM (Nano + Nano)</li><li>No Warranty. Compatible with Most GSM Carriers like T-Mobile, AT&T, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'oneplus-10-pro-5g-android-smartphone';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.7\", 1284 x 2778 pixels, Super Retina XDR OLED, 120Hz ProMotion, 1200 nits Peak Brightness, 4352mAh Battery, 15W MagSafe Wireless Charging</li><li>128GB ROM, 6GB RAM, No SD Card Slot, Apple A15 Bionic (5 nm), Hexa-Core (2x3.23 GHz Avalanche + 4x1.82 GHz Blizzard), Apple GPU 5-Core</li><li>Rear Camera: 12MP, f/1.5 (Wide) + 12MP, f/2.8 (Telephoto 3x) + 12MP, f/1.8 (Ultrawide), Front Camera: 12 MP, f/2.2, iOS 15, upgradable to iOS 26</li><li>2G: GSM 850/900/1800/1900 + CDMA 800/1900, 3G: HSDPA 850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/.../66, 5G: Sub6/mmWave - Nano-SIM + eSIM</li><li>No Warranty. Unlocked, Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'iphone-13-pro-max';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.5\", 1080 x 2400 pixels, Super AMOLED 120Hz HDR10+ Display, 4500mAh Battery, 25W Wired + 15W Wireless Charging, 4.5W Wireless PowerShare, Gorilla Glass 3</li><li>128GB ROM, 8GB RAM, microSDXC (shared SIM slot), Qualcomm SM8250 Snapdragon 865 5G (7 nm+), Octa-Core (1x2.84GHz A77 + 3x2.42GHz A77 + 4x1.80GHz A55), Adreno 650</li><li>Rear Camera: 12MP, f/1.8 (OIS) + 8MP, f/2.4 (3x telephoto) + 12MP, f/2.2 (123 ultrawide), Front Camera: 32MP, f/2.2, Android 10 (upgradable to Android 13), One UI 5.1</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700(AWS)/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/.../41/66/71, 5G: Sub6 (n2/n5/n41/n66/n71 USA, n1/n3/n5/n7/n8/n28/n40/n41/n78 Intl) - Nano-SIM, Single/Dual SIM</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'samsung-galaxy-s20-fe-5g';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>7.6\", 1768 x 2208 pixels, Foldable Dynamic AMOLED 2X 120Hz Main Display + 6.2\" 832 x 2268 Cover Display, 4400mAh Battery, 25W Wired, 11W Wireless, 4.5W Reverse Wireless</li><li>256GB ROM, 12GB RAM, No SD Card Slot, Qualcomm SM8350 Snapdragon 888 5G (5 nm), Octa-Core, Adreno 660</li><li>Rear Camera: 12MP, f/1.8 + 12MP, f/2.4 + 12MP, f/2.2, Cover Camera: 10MP, f/2.2, Under-Display Front Camera: 4MP, f/1.8, Android 11, One UI 3.1.1</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/20/28/38/40/41/66/..., 5G: Sub6 bands 1/3/5/7/8/20/28/38/40/41/66/77/78 - Nano-SIM + eSIM</li><li>No Warranty. Compatible with Most GSM Carriers like T-Mobile, AT&T, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'samsung-galaxy-z-fold-3-5g-cell-phone';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.49\", 1080 x 2400 pixels, IPS LCD 90Hz Display, 5000mAh Battery, 18W Wired Fast Charging</li><li>64GB ROM, 4GB RAM, microSDXC Card Slot (UFS 2.1), Qualcomm SM4350 Snapdragon 480 5G (8 nm), Octa-Core (2x2.0 GHz Kryo 460 + 6x1.8 GHz Kryo 460), Adreno 619</li><li>Rear Camera: 13MP, f/2.2 (PDAF) + 2MP, f/2.4 (Macro) + 2MP, f/2.4 (Mono), Front Camera: 16MP, f/2.1, Android 11, OxygenOS 11</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700(AWS)/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/20/25/26/28/38/39/40/41/66/71, 5G: Sub6 bands 2/25/41/66/71 - Single Nano-SIM</li><li>No Warranty. Compatible with Most GSM 5G Carriers like T-Mobile, Metro by T-Mobile, etc.</li></ul>"}', updated_at = now() WHERE slug = 'oneplus-nord-n200-5g';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.5\", 1242 x 2688 pixels, Super Retina XDR OLED (HDR10/Dolby Vision), 3969mAh Battery, Qi Wireless Charging + 18W PD Fast Charge (50% in 30 min)</li><li>256GB ROM, 4GB RAM, No SD Card Slot, Apple A13 Bionic (7 nm+), Hexa-Core (2x2.65 GHz Lightning + 4x1.8 GHz Thunder), Apple GPU (4-core graphics)</li><li>Rear Camera: 12MP, f/1.8 (wide) + 12MP, f/2.0 (telephoto) + 12MP, f/2.4 (ultrawide), Front Camera: 12 MP, f/2.2, iOS 13, upgradable to iOS 26.5</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700(AWS)/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/18/19/20/25/26/28/29/30/32/34/38/39/40/41/42/46/48/66/71, No 5G - Nano-SIM + eSIM (Single eSIM)</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, Sprint, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'apple-iphone-11-pro-max';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.6\", 1080 x 2340 pixels, Dynamic AMOLED 2X, 120Hz, HDR10+ Infinity-O Display, 4500mAh Battery, 45W Wired / 15W Wireless / Wireless Powershare</li><li>128GB / 256GB ROM, 8GB RAM, No SD Card Slot, Qualcomm SM8450 Snapdragon 8 Gen 1 (4 nm), Octa-Core (1x2.8GHz Cortex-X2 + 3x2.5GHz Cortex-A710 + 4x1.8GHz Cortex-A510), Adreno 730</li><li>Rear Camera: 50MP, f/1.8 + 10MP, f/2.4 (3x optical) + 12MP, f/2.2, Front Camera: 10MP, f/2.2, Android 12, One UI 4.1</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/20/25/26/28/38/40/41/66, 5G: Sub6 (n1/n2/n3/n5/n7/n78) + mmWave (n260/n261) - Nano-SIM + eSIM</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'samsung-galaxy-s22-cell-phone';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>4.7\", 750 x 1334 pixels, IPS LCD Retina HD Display, 1821mAh Battery, Wireless Qi Charging + IP67 Water Resistant</li><li>128GB ROM, 3GB RAM, No SD Card Slot, Apple A13 Bionic (7 nm), Hexa-Core (2x2.65 GHz Lightning + 4x1.8 GHz Thunder), Apple GPU 4-core</li><li>Rear Camera: 12MP, f/1.8 OIS, Front Camera: 7MP, f/2.2, iOS 13, upgradable to iOS 15</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/20/28/38/40/66, No 5G - Single SIM (Nano) + eSIM</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'iphone-9';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>5.8\", 1125 x 2436 pixels, Super Retina OLED (HDR10, Dolby Vision), 2716mAh Battery, 15W Wired Charging + Qi Wireless Charging</li><li>64GB / 256GB ROM, 3GB RAM, No SD Card Slot, Apple A11 Bionic (10 nm), Hexa-Core 2.39 GHz (2x Monsoon + 4x Mistral), Apple GPU (3-core)</li><li>Rear Camera: 12MP, f/1.8 (wide) + 12MP, f/2.4 (telephoto), Front Camera: 7 MP, f/2.2, iOS 11.1.1 (upgradable to iOS 16.7)</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/13/17/18/19/20/25/26/28/29/30/34/38/39/40/41/66, No 5G - Nano-SIM</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, Verizon, Sprint, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'iphone-x';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.7\", 1080 x 2400pixels, Infinity-O FHD+ Dynamic AMOLED 2X Display 120Hz, 5000mAh Battery, 45W Wired + 15W Wireless Powershare</li><li>256GB ROM, 12GB RAM, No SD Card Slot, Qualcomm SM8550 Snapdragon 8 Gen 2 (4 nm), Octa-Core, Adreno 740</li><li>Rear Camera: 50MP, f/1.8 + 12MP, f/2.2 + 10MP, f/2.4, Front Camera: 12 MP, f/2.2, Android 13, One UI 5.1</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/12/20/38/40/41, 5G: Sub6/mmWave - Single SIM</li><li>No Warranty. Compatible with Most GSM and CDMA Carriers like T-Mobile, AT&T, MetroPCS, etc.</li></ul>"}', updated_at = now() WHERE slug = 'samsung-universe-9';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.43\", 1080 x 2400 pixels, AMOLED Display (~409 ppi), 5000mAh Li-Po Battery, 33W Wired Fast Charging</li><li>128GB ROM, 6GB RAM, Dedicated microSDXC Slot, Qualcomm SM6115 Snapdragon 662 (11 nm), Octa-Core (4x2.0 GHz Kryo 260 Gold + 4x1.8 GHz Kryo 260 Silver), Adreno 610</li><li>Rear Camera: 48MP, f/1.7 (wide, PDAF) + 2MP, f/2.4 (macro) + 2MP, f/2.4 (depth), Front Camera: 16 MP, f/2.4, Android 11, ColorOS 11.1</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 850/900/2100, 4G LTE: bands 1/3/5/8/38/40/41, No 5G - Dual SIM (Nano-SIM, dual stand-by)</li><li>No Warranty. Compatible with Most GSM Carriers like T-Mobile, AT&T, MetroPCS, etc. CDMA Not Supported.</li></ul>"}', updated_at = now() WHERE slug = 'oppof19';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>6.1\", 1080 x 2340 pixels, 19.5:9 OLED FHD+ Display (~422 ppi), 3650mAh Battery, 22.5W Huawei SuperCharge</li><li>128GB ROM, 8GB RAM, NM (Nano Memory) Card Slot (shared SIM), HiSilicon Kirin 980 (7 nm), Octa-Core (2x2.6 GHz Cortex-A76 + 2x1.92 GHz Cortex-A76 + 4x1.8 GHz Cortex-A55), Mali-G76 MP10</li><li>Rear Camera: 40MP, f/1.8 + 16MP, f/2.2 (ultrawide) + 8MP, f/2.4 (3x telephoto), Front Camera: 32 MP, f/2.0, Android 9.0 Pie (upgradable to Android 10), EMUI 9.1/10</li><li>2G: GSM 850/900/1800/1900, 3G: HSDPA 800/850/900/1700/1900/2100, 4G LTE: bands 1/2/3/4/5/7/8/9/12/17/18/19/20/26/28/32/34/38/39/40, 5G: Not Supported - Nano-SIM (Single/Dual)</li><li>No Warranty. Compatible with Most GSM Carriers like T-Mobile, AT&T, MetroPCS, etc. (No CDMA - not compatible with Verizon/Sprint)</li></ul>"}', updated_at = now() WHERE slug = 'huawei-p30';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>14.2\", 3024 x 1964 pixels, Liquid Retina XDR mini-LED display, 1000 nits sustained / 1600 nits peak HDR, 1.6 kg, 100% recycled aluminum unibody chassis</li><li>Apple M1 Pro (5 nm), 8-core CPU (6 performance + 2 efficiency) up to 3.2 GHz, 14-core GPU, 16-core Neural Engine, 16GB LPDDR5 unified memory, 512GB PCIe NVMe SSD</li><li>3x Thunderbolt 4 (USB-C), HDMI 2.0, SDXC card slot, MagSafe 3, 3.5mm headphone jack, Wi-Fi 6 (802.11ax), Bluetooth 5.0, 1080p FaceTime HD webcam, backlit Magic Keyboard with Touch ID</li><li>70Wh lithium-polymer battery, up to 11h wireless web / 17h Apple TV video playback, 67W USB-C power adapter (96W optional), fast charge to 50% in 30 min, macOS</li><li>1-Year Limited Apple Warranty. Best for video editing, Xcode/software development, music production, and 3D work that needs sustained multi-core performance and a color-accurate HDR display.</li></ul>"}', updated_at = now() WHERE slug = 'macbook-pro';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>13.3\", 1920 x 1080 pixels, FHD LED touchscreen (10-point multi-touch), 0.95 kg / 2.09 lbs, 6.2-11.8 mm thick aluminum chassis (Mercury Gray / Earthy Gold)</li><li>Intel Core i5-L16G7 Lakefield (10 nm hybrid), 5 cores / 5 threads (1x Sunny Cove + 4x Tremont), 1.4 GHz base / 3.0 GHz turbo, Intel UHD Graphics Gen11 (64 EU), 8 GB LPDDR4X RAM (on-package, soldered), 256 GB eUFS storage</li><li>2x USB-C (USB 3.1, charge + DisplayPort), microSD card reader, 3.5 mm combo audio jack, Wi-Fi 6 802.11ax 2x2, Bluetooth 5.0, 1 MP (720p) front webcam, backlit island-style keyboard with fingerprint power key</li><li>42 Wh Li-ion battery, up to 17 hours rated video playback, 25W USB-C PD adapter (charges via either port), Windows 10 Home (full x86, no S Mode)</li><li>No manufacturer warranty included. Best for ultra-portable travel, all-day office and browsing on an always-connected fanless thin-and-light</li></ul>"}', updated_at = now() WHERE slug = 'samsung-galaxy-book';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>15\", 2496 x 1664 pixels (201 PPI), PixelSense IPS Touch Display, 3:2 aspect ratio, 60Hz, 10-point multi-touch, Corning Gorilla Glass 3, up to 427 nits, 1.542 kg, aluminum unibody chassis (Platinum/Matte Black)</li><li>AMD Ryzen 7 4980U Microsoft Surface Edition (7 nm, Zen 2), 8-Core/16-Thread, 2.00 GHz base / 4.40 GHz boost, AMD Radeon RX Vega 8 Graphics, 16GB DDR4 (soldered), 512GB Removable M.2 NVMe PCIe 3.0 SSD</li><li>1x USB-C 3.2 Gen 2 (Power Delivery / DisplayPort), 1x USB-A 3.2 Gen 2, 3.5mm headphone jack, Surface Connect port, Wi-Fi 6 (802.11ax), Bluetooth 5.0, 720p HD f/2.0 front webcam with Windows Hello IR, full-size backlit keyboard (1.3mm travel)</li><li>47.4 Wh Li-Polymer battery, up to 17.5 hours typical usage, 65W Surface Connect AC adapter (USB-A charging port on PSU), Windows 11 Home (upgradeable from Windows 10)</li><li>1-year limited hardware warranty. Best for productivity, business, students and creators wanting all-day battery, tall 3:2 touch display and lightweight metal build for office, coding and media.</li></ul>"}', updated_at = now() WHERE slug = 'microsoft-surface-laptop-4';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>14\", 1920 x 1080 pixels, FHD IPS Display, 16:9 aspect ratio, 300 nits, 100% sRGB, 1.48 kg, 16.3 mm aircraft-grade aluminium metal chassis, Starfall Grey</li><li>Intel Core i3-1005G1 (10nm Ice Lake), Dual-Core / 4 Threads, 1.2 GHz base up to 3.4 GHz, Intel UHD Graphics G1, 8GB LPDDR4X RAM, 256GB M.2 NVMe PCIe 3.0 SSD</li><li>1x HDMI 1.4, 2x USB-A 3.0, 1x USB-A 2.0, 2x USB-C (data + charging + DisplayPort), 3.5mm headphone jack, full-size SD card reader, Wi-Fi 6 (802.11ax), Bluetooth 5.1, 720p HD webcam with dual digital mic array, backlit keyboard</li><li>55Wh battery rated up to 13 hours video playback, 65W USB Type-C PD 3.0 fast charger (70% in ~55 min), Windows 11 Home</li><li>No Warranty. Thin-and-light pick for students, office productivity, browsing and media; not built for gaming or heavy GPU workloads.</li></ul>"}', updated_at = now() WHERE slug = 'infinix-inbook';
UPDATE products_product SET description = '{"delta": "", "html": "<ul><li>15.6\", 1920 x 1080 pixels, FHD IPS micro-edge WLED-backlit anti-glare display (60Hz), 4.92 lbs (2.23 kg), Shadow Black plastic chassis with Acid Green accents</li><li>Intel Core i5-10300H (14 nm, 2.5GHz base / 4.5GHz boost, Quad-Core / 8 threads), NVIDIA GeForce GTX 1650 4GB GDDR6, 8GB DDR4-2933MHz RAM (2 SO-DIMM slots, expandable to 32GB), 256GB PCIe NVMe M.2 SSD</li><li>1x USB-C 10Gbps (DisplayPort 1.4, HP Sleep and Charge), 3x USB-A 5Gbps, 1x HDMI 2.0, 1x RJ-45, 1x headphone/mic combo, Wi-Fi 5 (802.11ac 2x2) + Bluetooth 5.0, HP TrueVision HD 720p webcam, full-size backlit island-style keyboard with numeric keypad</li><li>3-cell 52.5Wh PG03XL Li-ion battery, up to 6h mixed usage / 9h video playback, 135W AC smart-pin adapter, Windows 10 Home 64-bit</li><li>1-year limited HP hardware warranty. Best for 1080p esports and AAA gaming at medium settings, video editing, and multitasking on a budget</li></ul>"}', updated_at = now() WHERE slug = 'hp-pavilion-15-dk1056wm';

COMMIT;
